questionvariables.text:
stm: [
  [lambda([u], u^2), lambda([n], n*(n+1)*(2*n+1)/6), "squares",
   "1^2 + 2^2 + 3^2 + \\cdots + n^2", "\\dfrac{n(n+1)(2n+1)}{6}",
   "1^2 + 2^2 + 3^2 + \\cdots + k^2", "n^2",
   ["1^2 + 2^2 + 3^2 = \\dfrac{3 \\times 4 \\times 7}{6}", "1^2 + 2^2 + 3^2 + 4^2 = \\dfrac{4 \\times 5 \\times 9}{6}"],
   "\\dfrac{(k+1)(k+2)(2k+3)}{6}"],
  [lambda([u], 2*u), lambda([n], n*(n+1)), "evens",
   "2 + 4 + 6 + \\cdots + 2n", "n(n+1)",
   "2 + 4 + 6 + \\cdots + 2k", "2n",
   ["2 + 4 + 6 = 3 \\times 4", "2 + 4 + 6 + 8 = 4 \\times 5"],
   "(k+1)(k+2)"],
  [lambda([u], 2^(u-1)), lambda([n], 2^n-1), "powers",
   "1 + 2 + 4 + \\cdots + 2^{n-1}", "2^n - 1",
   "1 + 2 + 4 + \\cdots + 2^{k-1}", "2^{n-1}",
   ["1 + 2 + 4 = 2^3 - 1", "1 + 2 + 4 + 8 = 2^4 - 1"],
   "2^{k+1} - 1"],
  [lambda([u], u*(u+1)), lambda([n], n*(n+1)*(n+2)/3), "products",
   "1 \\times 2 + 2 \\times 3 + 3 \\times 4 + \\cdots + n(n+1)", "\\dfrac{n(n+1)(n+2)}{3}",
   "1 \\times 2 + 2 \\times 3 + 3 \\times 4 + \\cdots + k(k+1)", "n(n+1)",
   ["1 \\times 2 + 2 \\times 3 + 3 \\times 4 = \\dfrac{3 \\times 4 \\times 5}{3}", "1 \\times 2 + 2 \\times 3 + 3 \\times 4 + 4 \\times 5 = \\dfrac{4 \\times 5 \\times 6}{3}"],
   "\\dfrac{(k+1)(k+2)(k+3)}{3}"],
  [lambda([u], 3*u-2), lambda([n], n*(3*n-1)/2), "step3",
   "1 + 4 + 7 + \\cdots + (3n-2)", "\\dfrac{n(3n-1)}{2}",
   "1 + 4 + 7 + \\cdots + (3k-2)", "3n - 2",
   ["1 + 4 + 7 = \\dfrac{3 \\times 8}{2}", "1 + 4 + 7 + 10 = \\dfrac{4 \\times 11}{2}"],
   "\\dfrac{(k+1)(3k+2)}{2}"]
];
idx: 1 + rand(5);
m: rand([3, 4]);
sname: stm[idx][3];
lhsn: stm[idx][4];
rhsn: stm[idx][5];
lhsk: stm[idx][6];
gen: stm[idx][7];
pmtex: stm[idx][8][m-2];
rkp1tex: stm[idx][9];
tvals: makelist(stm[idx][1](jj), jj, 1, m);
rval: stm[idx][2](m);
tm: stm[idx][1](m);
tkp1: stm[idx][1](k+1);
rkp1: factor(expand(stm[idx][2](k+1)));
dt1: stm[idx][1](k) + 1;
dr1: stm[idx][2](k) + 1;
dr0: stm[idx][2](k);
ta1: ev(apply("+", tvals) = rval, simp=false);
ta2: tkp1;
ta3: rkp1;
termsof(ex) := if safe_op(ex) = "+" then apply(append, map(termsof, args(ex))) else [ex];
cums: makelist(apply("+", rest(tvals, jj - m)), jj, 1, m);
psums(L) := makelist(apply("+", rest(L, jj - length(L))), jj, 1, length(L));
validate_pm(ex) := if safe_op(ex) # "=" then sconcat("P(", string(m), ") is a statement, so write it as an equation, with a left-hand side and a right-hand side.") else if listofvars(ex) # [] then sconcat("In P(", string(m), ") every n is replaced by ", string(m), ", so no letters are left.") else "";
validate_k(ex) := if every(lambda([v], is(v = k)), listofvars(ex)) then "" else "Write your answer in terms of k only.";

feedbackvariables.text:
Lt: termsof(lhs(ans1));
Rt: termsof(rhs(ans1));
/* Two readings of each side: fully flattened (so (1+4)+9 counts as three terms), and the top-level terms only (so a bracketed term such as (3*2-2) counts as one term). */
Lt0: if safe_op(lhs(ans1)) = "+" then args(lhs(ans1)) else [lhs(ans1)];
Rt0: if safe_op(rhs(ans1)) = "+" then args(rhs(ans1)) else [rhs(ans1)];
Lv: sort(map(lambda([u], ev(u, simp)), Lt));
Rv: sort(map(lambda([u], ev(u, simp)), Rt));
Lv0: sort(map(lambda([u], ev(u, simp)), Lt0));
Rv0: sort(map(lambda([u], ev(u, simp)), Rt0));
want: sort(tvals);
/* A third reading, for a general term typed without brackets, such as 3*1-2+3*2-2+3*3-2. Take the terms in the order typed and form their running totals. The side is the sum of the m terms when the running totals pass through every running total of the m terms and end on the last one. */
Lf: map(lambda([u], ev(u, simp)), Lt);
Rf: map(lambda([u], ev(u, simp)), Rt);
lpart: ev(is(subsetp(setify(cums), setify(psums(Lf)))) and is(last(psums(Lf)) = last(cums)), simp);
rpart: ev(is(subsetp(setify(cums), setify(psums(Rf)))) and is(last(psums(Rf)) = last(cums)), simp);
lok: is(Lv = want) or is(Lv0 = want) or lpart;
rok: is(Rv = want) or is(Rv0 = want) or rpart;
sumok: if lok or rok then 1 else 0;
/* The sum written on both sides is true but is not P(m), so it is sent to the false branch of node 1. */
other: if lok and rok then rval + 1 else if lok then ev(rhs(ans1), simp) else ev(lhs(ans1), simp);
/* A left-hand side equal to the last term counts as one term even when typed as a sum, such as 3*3-2. */
shape: [if is(ev(lhs(ans1), simp) = tm) then 1 else length(Lt), ev(lhs(ans1), simp)];
